  const [openTabs, setOpenTabs] = useState(() => {
    try {
      const saved = localStorage.getItem("marks_openTabs");
      if (saved) {
        const parsed = JSON.parse(saved);
        if (Array.isArray(parsed) && parsed.length > 0) return parsed;
      }
    } catch {}
    return [];
  });

  const [activeTab, setActiveTab] = useState(() => {
    try {
      return localStorage.getItem("marks_activeTab") || "dashboard";
    } catch {
      return "dashboard";
    }
  });

  // Listen to navigation state from ERP Apps or URL parameters
  useEffect(() => {
    if (location.state && location.state.tab) {
      setActiveTab(location.state.tab);
      setSelectedSubItem(location.state.tab === "dashboard" ? "" : location.state.tab);
      if (location.state.tab === "dashboard") {
        setOpenMenu("");
      } else if (!openTabs.includes(location.state.tab)) {
        setOpenTabs((prev) => [...prev, location.state.tab]);
      }
    } else if (urlTab) {
      setActiveTab(urlTab);
      setSelectedSubItem(urlTab);
      if (!openTabs.includes(urlTab)) {
        setOpenTabs((prev) => [...prev, urlTab]);
      }
    }
  }, [location.state, urlTab]);

