  const handleReplicateWeightage = () => {
    if (existingWeightageFilterClass === "-Select-") {
      alert("Please select a Class to replicate from");
      return;
    }
    if (selectedReplicateClasses.length === 0) {
      alert("Please select at least one target Class to replicate to");
      return;
    }

    const sourceRecords = scholasticWeightageList.filter(
      (item) => item.className === existingWeightageFilterClass
    );

    if (sourceRecords.length === 0) {
      alert(`No exam weightage records found for ${existingWeightageFilterClass} to replicate.`);
      return;
    }

    const replicated = [];
    selectedReplicateClasses.forEach((targetClass) => {
      sourceRecords.forEach((rec) => {
        replicated.push({
          ...rec,
          sNo: scholasticWeightageList.length + replicated.length + 1,
          className: targetClass,
        });
      });
    });

    setScholasticWeightageList([...replicated, ...scholasticWeightageList]);
    setSelectedReplicateClasses([]);
    setIsReplicateClassDropdownOpen(false);
    alert(`Successfully replicated ${sourceRecords.length} records to ${selectedReplicateClasses.join(", ")}!`);
  };

