  const handleExportMarksEntryStatusExcel = () => {
    const headers = "S.No,Class/Standard,Subject,Teacher,Term,Exam,Total Students,Marks Entered,Pending,Status,Last Updated\n";
    const rows = marksEntryStatusData.map(r => 
      `${r.sNo},"${r.classOrStandard}","${r.subject}","${r.teacher}","${r.term}","${r.exam}",${r.totalStudents},${r.marksEntered},${r.pending},"${r.status}","${r.lastUpdated}"`
    ).join("\n");
    const blob = new Blob([headers + rows], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `Marks_Entry_Status_Report_${new Date().toISOString().slice(0,10)}.csv`;
    link.click();
    URL.revokeObjectURL(url);
  };

