  const handleSaveStudentSubjects = (e) => {
    e.preventDefault();
    if (selectedStudentsForAssign.length === 0) {
      alert("Please select at least one Student");
      return;
    }
    if (selectedSubjectsForStudentAssign.length === 0) {
      alert("Please select at least one Subject");
      return;
    }

    const newEntries = [];
    selectedStudentsForAssign.forEach((student) => {
      selectedSubjectsForStudentAssign.forEach((subject) => {
        newEntries.push({
          sNo: studentSubjectAssignments.length + newEntries.length + 1,
          student: student,
          className: studentAssignClass,
          subject: subject,
          code: subject.substring(0, 3).toUpperCase(),
        });
      });
    });

    setStudentSubjectAssignments([...studentSubjectAssignments, ...newEntries]);
    setSelectedStudentsForAssign([]);
    setSelectedSubjectsForStudentAssign([]);
    setIsStudentDropdownOpen(false);
    setIsSubjectDropdownOpen(false);
    alert("Subject(s) assigned to student(s) successfully!");
  };

